import (
	"fmt"
	"os"
)

func writeLog(name string, stops []string) error {
	f, err := os.Create(name)
	if err != nil {
		return err
	}
	defer f.Close()
	for i, s := range stops {
		fmt.Fprintf(f, "stop %d: %s\n", i+1, s)
	}
	return nil
}

func main() {
	err := writeLog("log.txt", []string{"Elm St", "Oak Ave", "Pine Rd"})
	if err != nil {
		fmt.Println("cannot write:", err)
		return
	}
	data, err := os.ReadFile("log.txt")
	if err != nil {
		fmt.Println("cannot read:", err)
		return
	}
	fmt.Print(string(data))
}

