package main

import "fmt"

func describe(v any) string {
	switch x := v.(type) {
	case int:
		return fmt.Sprintf("int %d, doubled %d", x, x*2)
	case string:
		return fmt.Sprintf("string %q with %d bytes", x, len(x))
	case bool:
		if x {
			return "bool: yes"
		}
		return "bool: no"
	case nil:
		return "nothing at all"
	default:
		return fmt.Sprintf("something else: %T", x)
	}
}

func main() {
	fmt.Println(describe(21))
	fmt.Println(describe("go"))
	fmt.Println(describe(true))
	fmt.Println(describe(nil))
	fmt.Println(describe(4.5))
}

